/* Responsive pictures from the media manifest.
 *
 * Variants are pre-generated by ops/media.mjs at a fixed set of widths — never on demand — so no
 * request can ask for a size nobody planned. File names carry the first 8 characters of the
 * original's sha256, so a replaced photo gets new URLs and every variant can be cached forever.
 * Crops are CSS (object-fit: cover, object-position from the manifest's focal point): one set of
 * variants per photo serves every block, and an editor moving the focal point needs no re-encode.
 * The focal point is written into the stylesheet by mediaCss(), not into a style attribute, so
 * the Content-Security-Policy can refuse inline styles.
 *
 * Every photo slot (a block's photo, photos or circle, a room or step photo, an event's photo)
 * takes one of three things, so any photo can be swapped by pasting a link:
 *   "m-craft-table"                                   a photo in the media library
 *   "https://…"                                       a link to a photo anywhere
 *   { "link": "https://…", "alt": "…", "focal": [x, y] }   a link with its description and focal point
 * A linked photo is fetched once, at build time, by ops/media.mjs and served from this site like
 * any library photo: a visitor's browser never asks the other site for it.
 */

import crypto from "node:crypto";
import { html, attrs } from "./html.mjs";

export const WIDTHS = [360, 640, 960, 1280, 1600];
export const FORMATS = [
  { ext: "avif", type: "image/avif" },
  { ext: "webp", type: "image/webp" },
  { ext: "jpg", type: null },
];

export function variantWidths(item) {
  const ws = WIDTHS.filter((w) => w <= item.width);
  return ws.length ? ws : [item.width];
}

export const variantName = (item, w, ext) => `${item.id}.${item.sha256.slice(0, 8)}-${w}.${ext}`;

const LINK_RE = /^https?:\/\//i;
const LOCAL_HOSTS = new Set(["localhost", "127.0.0.1", "[::1]"]);

/* A linked photo's id: the same link and focal point always make the same id. */
export const linkId = (link, focal = null) =>
  "l-" + crypto.createHash("sha256").update(focal ? `${link}#${focal.join(",")}` : link).digest("hex").slice(0, 12);

/* { id, link, alt, focal } for a photo slot's value, or null when it is none of the three forms. */
export function photoRef(ref) {
  if (typeof ref === "string") return LINK_RE.test(ref) ? { id: linkId(ref), link: ref, alt: null, focal: null } : { id: ref, link: null, alt: null, focal: null };
  if (ref && typeof ref === "object" && !Array.isArray(ref) && typeof ref.link === "string") {
    const focal = Array.isArray(ref.focal) ? ref.focal : null;
    return { id: linkId(ref.link, focal), link: ref.link, alt: typeof ref.alt === "string" ? ref.alt : null, focal };
  }
  return null;
}

const privateHost = (h) => LOCAL_HOSTS.has(h) || /^(10|127)\./.test(h) || /^192\.168\./.test(h) || /^172\.(1[6-9]|2\d|3[01])\./.test(h) || /^169\.254\./.test(h) || h.endsWith(".local") || h.endsWith(".internal") || h.startsWith("[");

/* Why a photo slot's value cannot be published, as a list of reasons (empty when it can).
   media: the set of library ids. production: refuse links a build machine should never fetch. */
export function photoProblems(ref, { media = null, production = false } = {}) {
  const r = photoRef(ref);
  if (!r) return ["a photo is a library id, a link, or { link, alt, focal }"];
  const out = [];
  if (!r.link) {
    if (media && !media.has(r.id)) out.push(`photo "${r.id}" is not in media/manifest.json`);
    return out;
  }
  let u = null;
  try { u = new URL(r.link); } catch { out.push(`photo link "${r.link}" is not a web address`); }
  if (u) {
    const local = LOCAL_HOSTS.has(u.hostname);
    if (u.protocol !== "https:" && !(u.protocol === "http:" && local && !production)) out.push(`photo link "${r.link}" must start with https://`);
    if (u.username || u.password) out.push(`photo link "${r.link}" must not carry a user name or password`);
    if (production && privateHost(u.hostname)) out.push(`photo link "${r.link}" points at a private address`);
    if (/drive\.google\.com\/drive\/(u\/\d+\/)?folders\//.test(r.link)) out.push(`photo link "${r.link}" is a Drive folder; open the photo and copy its own link`);
  }
  if (r.link.length > 2000) out.push("a photo link is at most 2000 characters");
  if (typeof ref === "object") {
    if (ref.alt != null && typeof ref.alt !== "string") out.push(`photo link "${r.link}": alt must be text`);
    if (ref.focal != null && !(Array.isArray(ref.focal) && ref.focal.length === 2 && ref.focal.every((n) => typeof n === "number" && n >= 0 && n <= 100))) out.push(`photo link "${r.link}": focal must be two numbers from 0 to 100`);
  }
  return out;
}

/* Every photo slot in a record: keys photo and media hold one, photos holds a list. */
export function photoSlots(obj, at = "") {
  const out = [];
  const walk = (v, where) => {
    if (Array.isArray(v)) return v.forEach((x, i) => walk(x, `${where}[${i}]`));
    if (!v || typeof v !== "object") return;
    for (const [k, x] of Object.entries(v)) {
      const here = where ? `${where}.${k}` : k;
      if ((k === "photo" || k === "media") && x != null && (typeof x === "string" || typeof x.link === "string")) out.push({ ref: x, at: here });
      else if (k === "photos" && Array.isArray(x)) x.forEach((p, i) => out.push({ ref: p, at: `${here}[${i}]` }));
      else walk(x, here);
    }
  };
  walk(obj, at);
  return out;
}

/* <picture> for one photo slot's value (a library id, a link, or { link, alt, focal }).
   sizes:  the CSS width the image is drawn at, for each layout (required — a wrong guess
           downloads the 1600 for a 300-pixel slot, which is the live site's whole problem).
   eager:  the one image above the fold gets fetchpriority=high and no lazy loading. */
export function picture(ctx, ref, { sizes, eager = false, className = null, alt = null } = {}) {
  const r = photoRef(ref);
  const item = r && ctx.media.get(r.id);
  if (!item) throw new Error(r?.link ? `linked photo ${r.link} was not fetched` : `media ${r?.id ?? ref} is not in media/manifest.json`);
  const ws = variantWidths(item);
  const srcset = (ext) => ws.map((w) => `/media/${variantName(item, w, ext)} ${w}w`).join(", ");
  const fallbackW = ws.find((w) => w >= 960) || ws[ws.length - 1];
  return html`<picture${attrs({ class: [`media-${item.id}`, className].filter(Boolean).join(" ") })}>${FORMATS.filter((f) => f.type).map((f) => html`<source type="${f.type}" srcset="${srcset(f.ext)}" sizes="${sizes}">`)}<img${attrs({
    src: `/media/${variantName(item, fallbackW, "jpg")}`,
    srcset: srcset("jpg"),
    sizes,
    width: item.width,
    height: item.height,
    alt: alt ?? r.alt ?? item.alt ?? ctx.t("media.linkAlt"),
    loading: eager ? null : "lazy",
    decoding: eager ? null : "async",
    fetchpriority: eager ? "high" : null,
  })}></picture>`;
}

/* One rule per photo: its focal point. */
export function mediaCss(items) {
  return items.map((m) => {
    const [fx, fy] = m.focal || [50, 50];
    return `.media-${m.id} img{object-position:${fx}% ${fy}%}`;
  }).join("\n") + "\n";
}
